import { MakeLogicType, actions, afterMount, connect, kea, listeners, path } from 'kea'
import { combineUrl, router } from 'kea-router'

import { teamLogic } from 'scenes/teamLogic'
import { urls } from 'scenes/urls'

import { getIntegrationsAuthorizeRetrieveUrl } from 'products/integrations/frontend/generated/api'

import { inboxSetupLogic } from './inboxSetupLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inboxAgentActivationLogicValues {
    currentTeamId: number | null // teamLogic
    error: string | null // inboxSetupLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inboxAgentActivationLogicActions {
    start: () => { value: true }
}

export type inboxAgentActivationLogicType = MakeLogicType<
    inboxAgentActivationLogicValues,
    inboxAgentActivationLogicActions
>

export const inboxAgentActivationLogic = kea<inboxAgentActivationLogicType>([
    path(['products', 'signals', 'inbox', 'inboxAgentActivationLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId'], inboxSetupLogic, ['error']],
    })),
    actions({ start: true }),
    listeners(({ values }) => ({
        start: async (_, breakpoint) => {
            const projectId = values.currentTeamId
            if (!projectId || inboxSetupLogic.values.saving) {
                return
            }
            inboxSetupLogic.actions.setError(null)
            await inboxSetupLogic.asyncActions.loadSetup()
            breakpoint()
            if (projectId !== values.currentTeamId || values.error) {
                return
            }
            const state = inboxSetupLogic.values.savedState
            if (!state) {
                return
            }
            if (state.completed_at) {
                router.actions.replace(urls.inbox(), { agent_setup: 'complete' })
                return
            }
            if (state.draft) {
                router.actions.replace(urls.inbox(), {
                    onboarding_step: state.draft.step,
                    agent_setup: 'return',
                })
                return
            }
            const next = urls.project(
                projectId,
                combineUrl(urls.inbox(), {
                    setup: 'github-first',
                    onboarding_step: 'quick',
                    agent_setup: 'return',
                }).url
            )
            const authorizeUrl = combineUrl(getIntegrationsAuthorizeRetrieveUrl(String(projectId)), {
                kind: 'github',
                next,
            }).url
            router.actions.replace(urls.inboxActivate(), { onboarding_step: 'quick' })
            inboxSetupLogic.actions.expose()
            inboxSetupLogic.actions.connectGithub(authorizeUrl)
        },
    })),
    afterMount(({ actions }) => actions.start()),
])
